  if($taskFile.ReadByte() -ne -1){throw 'BOOTSTRAP_EXACT_EOF'};return [Convert]::ToHexString($taskHash.GetHashAndReset())
 }catch{$taskBody=$_;if($null -eq $script:taskPrimaryRaw){$script:taskPrimaryRaw=$_};throw}
